-- 엔티티를 넘기면 관리된다

@Test
@Transactional
void 엔티티_타입() {
    em.clear();
    List<Member> ms = memberRepository.findByUsername("m1", Member.class);
    SessionImpl s = em.unwrap(SessionImpl.class);
    System.out.println("엔티티 수: " +
            s.getPersistenceContext().getNumberOfManagedEntities());

    ms.get(0).setAge(99);
    em.flush();
}

