-- 화면마다 다른 타입을 준다

@GetMapping("/members/{name}")
public Object one(@PathVariable String name,
                  @RequestParam(defaultValue = "summary") String view) {
    return switch (view) {
        case "name" -> memberRepository.findByUsername(name,
                UsernameOnly.class);
        case "full" -> memberRepository.findByUsername(name,
                Member.class);
        default     -> memberRepository.findByUsername(name,
                MemberSummary.class);
    };
}

